def gen(rng):
    alpha = 'ABCDExyz0123'

    def fresh_names(k, used):
        res = []
        while len(res) < k:
            s = ''.join(rng.choice(alpha) for _ in range(rng.randint(1, 3)))
            if s not in used:
                used.append(s)
                res.append(s)
        return res

    def build(names, shape):
        edges = []
        open_ = [names[0]]
        kids = {names[0]: 0}
        for idx in range(1, len(names)):
            v = names[idx]
            if shape == 'chain':
                p = names[idx - 1]
            else:
                i = rng.randrange(len(open_))
                p = open_[i]
                kids[p] += 1
                if kids[p] == 2:
                    open_[i] = open_[-1]
                    open_.pop()
            edges.append((p, v))
            kids[v] = 0
            open_.append(v)
        return edges

    def fmt(edges):
        return str(len(edges)) + '\n' + '\n'.join(a + ' ' + b for a, b in edges)

    tests = [
        fmt([('A', 'B')]),
        fmt([('A', 'A')]),
        fmt([('A', 'B'), ('B', 'A')]),
        fmt([('A', 'B'), ('A', 'B')]),
        fmt([('A', 'B'), ('C', 'D')]),
        fmt([('A', 'B'), ('A', 'C'), ('A', 'D')]),
        fmt([('A', 'B'), ('A', 'C'), ('B', 'D'), ('B', 'E')]),
    ]
    for _ in range(70):
        used = []
        k = rng.randint(1, 12)
        names = fresh_names(k + 1, used)
        edges = build(names, rng.choice(['rand', 'rand', 'chain']))
        if rng.random() < 0.25:
            p = rng.choice(names)
            for c in fresh_names(rng.randint(1, 2), used):
                edges.append((p, c))
            # make the parent really exceed two children only sometimes
        if rng.random() < 0.25 and edges:
            edges.insert(rng.randrange(len(edges) + 1), rng.choice(edges))
        if rng.random() < 0.25:
            t = rng.randint(1, 3)
            cn = fresh_names(t, used)
            for i in range(t):
                edges.append((cn[i], cn[(i + 1) % t]))
        if rng.random() < 0.25:
            sub = fresh_names(rng.randint(1, 4), used)
            edges += build(sub, 'rand') if len(sub) > 1 else [(sub[0], fresh_names(1, used)[0])]
        rng.shuffle(edges)
        s = fmt(edges)
        if len(s) <= 400:
            tests.append(s)

    def big(n, shape, extra=None):
        names = ['n' + str(i) for i in range(n + 1)]
        rng.shuffle(names)
        edges = build(names, shape)
        if extra == 'dup':
            edges.append(edges[len(edges) // 2])
        elif extra == 'cycle':
            edges += [('c1', 'c2'), ('c2', 'c3'), ('c3', 'c1')]
        elif extra == 'root':
            edges += [('r0', 'r1'), ('r0', 'r2')]
        elif extra == 'kids':
            edges.append((names[0], 'extra1'))
            edges.append((names[0], 'extra2'))
        rng.shuffle(edges)
        return fmt(edges)

    tests.append(big(100000, 'rand'))
    tests.append(big(99997, 'rand', 'root'))
    tests.append(big(99996, 'rand', 'cycle'))
    tests.append(big(4999, 'chain'))
    tests.append(big(60000, 'rand', 'dup'))
    tests.append(big(60000, 'rand', 'kids'))
    return tests
